import assert from 'node:assert/strict';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {chromium} from 'playwright';
import {createClient} from '@supabase/supabase-js';
import {sessaoQa} from './sessoes-qa-concorrencia-20261116.mjs';
const root='output/timeouts-concorrencia-26-20261116',out=root+'/'+(process.env.QA_FASE||'acesso-timeout-publicado'),base=process.env.QA_URL||'https://patio-gestao-peach.vercel.app';await mkdir(out,{recursive:true});
const env=Object.fromEntries((await readFile('.env.local','utf8')).split(/\r?\n/).filter(l=>/^VITE_SUPABASE_/.test(l)).map(l=>{const i=l.indexOf('=');return[l.slice(0,i),l.slice(i+1).trim().replace(/^['"]|['"]$/g,'')]}));
const contas=JSON.parse(await readFile('output/contas-teste/20261019/credenciais.local.json','utf8')).contas;
const pacote=JSON.parse(await readFile(root+'/pacote-timeout.json','utf8')),health=await fetch(base+'/health.json?qa='+Date.now()).then(r=>r.json());assert.equal(health.build,pacote.build);
const sessoes=[];for(const c of contas){const cli=createClient(env.VITE_SUPABASE_URL,env.VITE_SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:false,autoRefreshToken:false}});sessoes.push(await sessaoQa(cli,c));}
const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'}),resultados=[],falhas=[],errosJs=[];let proximo=0;
const salvar=()=>writeFile(out+'/resultado.json',JSON.stringify({build:health.build,url:base,metodo:'Build real e permissões reais; falhas de transporte e negação simuladas só no navegador. Nenhuma gravação.',resultados,falhas,errosJs},null,2));
const nomes={assistencia_tecnica:'Ordem de reparo',manutencao_campo:'Visita técnica',limpeza:'Serviço de limpeza'};
async function usuario(i){const c=contas[i],auto=c.ramo==='automotivo',mobile=i%2===1,ctx=await browser.newContext({viewport:{width:mobile?390:1920,height:900},isMobile:mobile,hasTouch:mobile,serviceWorkers:'block',locale:'pt-BR'});
 await ctx.addInitScript(({session,base,nome})=>{if(location.origin!==base)return;localStorage.setItem('sb-hzihxtjirttetnfdujcx-auth-token',JSON.stringify(session));window.qaAcesso={calls:0,modo:nome};const original=window.fetch.bind(window);window.fetch=(input,init)=>{const url=typeof input==='string'?input:input.url||String(input);if(url.endsWith('/rpc/consultar_meu_acesso')){window.qaAcesso.calls++;const modo=window.qaAcesso.modo;window.qaAcesso.modo=null;if(modo==='TimeoutError'||modo==='AbortError')return Promise.reject(new DOMException('Tempo esgotado no teste controlado',modo));if(modo==='negado')return Promise.resolve(new Response(JSON.stringify({code:'42501',message:'Acesso revogado no teste controlado'}),{status:403,headers:{'content-type':'application/json'}}))}return original(input,init)}},{session:sessoes[i],base,nome:mobile?'AbortError':'TimeoutError'});
 const p=await ctx.newPage();p.setDefaultTimeout(20000);p.on('pageerror',e=>errosJs.push({perfil:c.especialidade,erro:e.message}));const pass=(nome,t)=>resultados.push({perfil:c.especialidade,mobile,nome,ok:true,segundos:(performance.now()-t)/1000});
 const foco=()=>p.evaluate(()=>{Object.defineProperty(document,'visibilityState',{value:'hidden',configurable:true});window.dispatchEvent(new Event('visibilitychange'));delete document.visibilityState;window.dispatchEvent(new Event('visibilitychange'))});
 try{
  let t=performance.now();await p.goto(base+(auto?'/ordens-servico':'/atendimentos'),{waitUntil:'domcontentloaded'});const novo=p.getByRole('button',{name:auto?'Nova OS':nomes[c.ramo],exact:true});await novo.waitFor();assert.equal(await p.evaluate(()=>window.qaAcesso.calls),2);pass('Abertura recupera timeout serializado',t);
  await novo.click();const cliente=p.locator('dialog[open]').getByRole('combobox',{name:'Cliente',exact:true});await cliente.fill('QA rascunho não salvar');
  t=performance.now();const antes=await p.evaluate(()=>{window.qaAcesso.modo='TimeoutError';return window.qaAcesso.calls});const recuperou=p.waitForResponse(r=>r.url().endsWith('/rpc/consultar_meu_acesso')&&r.status()===200);await foco();await recuperou;await p.waitForFunction(n=>window.qaAcesso.calls===n+2,antes);assert.equal(await cliente.inputValue(),'QA rascunho não salvar');pass('Timeout preserva formulário e recupera consulta',t);
  t=performance.now();const negacao=await p.evaluate(()=>{window.qaAcesso.modo='negado';return window.qaAcesso.calls});await foco();await p.getByText('Não conseguimos validar seu acesso.',{exact:true}).waitFor();assert.equal(await p.evaluate(()=>window.qaAcesso.calls),negacao+1);assert.equal(await cliente.count(),0);pass('Permissão negada bloqueia sem repetir',t);console.log('PASS acesso',c.especialidade);
 }catch(e){falhas.push({perfil:c.especialidade,erro:e.message});await p.screenshot({path:out+'/'+c.especialidade+'-falha.png'});console.log('FAIL acesso',c.especialidade,e.message)}finally{await ctx.close();await salvar()}}
try{await Promise.all(Array.from({length:4},async()=>{while(proximo<contas.length){const i=proximo++;await usuario(i)}}))}finally{await browser.close();await salvar()}assert.equal(falhas.length,0);assert.equal(errosJs.length,0);assert.equal(resultados.length,78);
